"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["53772"],{99291(e){e.exports=JSON.parse('{"id":"F381","slug":"var-backtest-kupiec","name":"VaR Backtest: Exceptions and Kupiec Test","subject":"Risk Management","section":"Risk","topic":"Backtesting","level":"Intermediate","aliases":["backtesting VaR","traffic light test","proportion of failures","VaR exceptions"],"formula":{"latex":"LR_{POF}=-2\\\\ln\\\\left[(1-p)^{N-x}p^{x}\\\\right]+2\\\\ln\\\\left[\\\\left(1-\\\\tfrac{x}{N}\\\\right)^{N-x}\\\\left(\\\\tfrac{x}{N}\\\\right)^{x}\\\\right]","also":[],"text":"Kupiec statistic = -2 x ln[(1-p)^(N-x) x p^x] + 2 x ln[(1 - x/N)^(N-x) x (x/N)^x]; compare with 3.84 (5% level, 1 degree of freedom)"},"symbols":[{"symbol":"N","meaning":"Number of days tested","unit":"days"},{"symbol":"x","meaning":"Number of days on which the loss exceeded VaR (exceptions)","unit":"number"},{"symbol":"p","meaning":"Expected exception rate: 1 minus the VaR confidence","unit":"percent"},{"symbol":"LR","meaning":"Likelihood-ratio statistic. Above 3.84 rejects the model at the 5% level","unit":"number"}],"when_to_use":"Use it to check whether a VaR model is calibrated. A 99% VaR should be exceeded about 1 day in 100. Too many exceptions means risk is understated, and too few means capital is wasted. The Basel traffic light for 250 days at 99% is green for 0 to 4 exceptions, yellow for 5 to 9 and red for 10 or more.","worked_example":{"problem":"Over 250 days a 99% VaR model was exceeded 6 times.","inputs":{"n":250,"x":6,"c":99},"steps":[{"label":"Expected exception rate p = 1 - confidence","working":"1-0.99","value":"1.00%"},{"label":"Expected exceptions = N x p","working":"250 x 0.01","value":"2.50"},{"label":"Observed rate = x / N","working":"6 / 250","value":"2.40%"},{"label":"Kupiec LR statistic","working":"-2 x ln((1-0.01)^(250-6) x 0.01^6)+2 x ln((1-6 / 250)^(250-6) x (6 / 250)^6)","value":"3.555"},{"label":"Reject the model at 5%? (1 = yes, 0 = no)","working":"1 if 3.55535>3.841 else 0","value":"0"}],"answer":"With 99% confidence, about 2.50 exceptions were expected and 6 occurred (an observed rate of 2.40%). The Kupiec statistic is 3.555, just below the 3.84 cut-off, so the model is not rejected at the 5% level. Under the Basel traffic light, 6 exceptions fall in the yellow zone."},"calculator":{"available":true,"inputs":[{"id":"n","label":"Days tested","unit":"days","type":"number","default":250,"hint":"","min":10},{"id":"x","label":"Exceptions","unit":"number","type":"number","default":6,"hint":"","min":1},{"id":"c","label":"VaR confidence level","unit":"%","type":"number","default":99,"hint":""}],"checks":[{"expr":"x>=1 and x<n and c>0.5 and c<1","message":"Exceptions must be at least 1 and fewer than the days tested."}],"steps":[{"id":"p","label":"Expected exception rate p = 1 - confidence","expr":"1-c","format":"pct2"},{"id":"exp","label":"Expected exceptions = N x p","expr":"n*p","format":"num2"},{"id":"rate","label":"Observed rate = x / N","expr":"x/n","format":"pct2"},{"id":"lr","label":"Kupiec LR statistic","expr":"-2*ln((1-p)^(n-x)*p^x)+2*ln((1-x/n)^(n-x)*(x/n)^x)","format":"num3"},{"id":"reject","label":"Reject the model at 5%? (1 = yes, 0 = no)","expr":"1 if lr>3.841 else 0","format":"num0"}],"results":["lr","reject"],"percent_inputs_typed_as_whole_numbers":true,"tested_against":{"exp":2.5,"lr":3.5553547710617437,"reject":0}},"finder":{"finds":"Whether a VaR model has the right number of exceptions","needs":"Days tested, exceptions, confidence"},"related":[{"slug":"var-parametric","name":"Value at Risk: Parametric (Variance-Covariance)"},{"slug":"binomial-option-two-step","name":"Binomial Option Pricing (Two Steps)"}],"related_ids":["F378","F330"],"group":"Risk and quantitative methods","mathml":"<span class=\\"katex\\"><math xmlns=\\"http://www.w3.org/1998/Math/MathML\\" display=\\"block\\"><semantics><mrow><mi>L</mi><msub><mi>R</mi><mrow><mi>P</mi><mi>O</mi><mi>F</mi></mrow></msub><mo>=</mo><mo>\u2212</mo><mn>2</mn><mi>ln</mi><mo>\u2061</mo><mrow><mo fence=\\"true\\">[</mo><mo stretchy=\\"false\\">(</mo><mn>1</mn><mo>\u2212</mo><mi>p</mi><msup><mo stretchy=\\"false\\">)</mo><mrow><mi>N</mi><mo>\u2212</mo><mi>x</mi></mrow></msup><msup><mi>p</mi><mi>x</mi></msup><mo fence=\\"true\\">]</mo></mrow><mo>+</mo><mn>2</mn><mi>ln</mi><mo>\u2061</mo><mrow><mo fence=\\"true\\">[</mo><msup><mrow><mo fence=\\"true\\">(</mo><mn>1</mn><mo>\u2212</mo><mstyle displaystyle=\\"false\\" scriptlevel=\\"0\\"><mfrac><mi>x</mi><mi>N</mi></mfrac></mstyle><mo fence=\\"true\\">)</mo></mrow><mrow><mi>N</mi><mo>\u2212</mo><mi>x</mi></mrow></msup><msup><mrow><mo fence=\\"true\\">(</mo><mstyle displaystyle=\\"false\\" scriptlevel=\\"0\\"><mfrac><mi>x</mi><mi>N</mi></mfrac></mstyle><mo fence=\\"true\\">)</mo></mrow><mi>x</mi></msup><mo fence=\\"true\\">]</mo></mrow></mrow><annotation encoding=\\"application/x-tex\\">LR_{POF}=-2\\\\ln\\\\left[(1-p)^{N-x}p^{x}\\\\right]+2\\\\ln\\\\left[\\\\left(1-\\\\tfrac{x}{N}\\\\right)^{N-x}\\\\left(\\\\tfrac{x}{N}\\\\right)^{x}\\\\right]</annotation></semantics></math></span>","alsoMathml":[],"prev":{"slug":"mm-levered-value","name":"Value of a Levered Firm (Modigliani-Miller with Taxes)"},"next":{"slug":"variance-sd","name":"Variance and Standard Deviation of Returns"},"lesson":null,"total":522}')}}]);